/* StudyT · Free Fire Tournament 2026. Integrates after Digital ID confirmation.
 * Requires supabase/migrations/20261116_freefire_tournament.sql for live operation.
 * Never store credentials, sensitive identities or scores in localStorage. */
(()=>{'use strict';
const ADMIN=/admin\.html(?:$|[?#])/i.test(location.pathname);
const $=(s,r=document)=>r.querySelector(s), $$=(s,r=document)=>[...r.querySelectorAll(s)];
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const safeNum=(v,a,b)=>{const n=Number(v);return Number.isInteger(n)&&n>=a&&n<=b?n:null};
const lng=()=>document.documentElement.lang==='en';
const t=(vi,en)=>lng()?en:vi;
const fmt=d=>d?new Date(d).toLocaleString(lng()?'en-US':'vi-VN',{dateStyle:'short',timeStyle:'short'}):'—';
const modes=[['survival','Sinh tồn Solo','Solo Battle Royale','19/11/2026','5 trận','5 matches'],['clash','Tử chiến','Clash Squad','22/11/2026','5 trận 4v4','5 team matches'],['duel','Độc Lang Chiến','Lone Wolf','25/11/2026','1v1','1v1']];
const placement=p=>p===1?20:p===2?17:p===3?15:p===4?13:p===5?12:p<=10?16-p:p<=15?5:p<=20?3:p<=30?2:p<=40?1:0;
const st={draws:[],official:null,identity:null,regs:[],players:[],br:[],clash:[],duel:[],accounts:[],identities:[],allRegs:[],tab:'rules',adminTab:'registrations',busy:false,loaded:false};
const client=()=>typeof sb!=='undefined'&&sb?sb:null;
const user=()=>typeof me!=='undefined'&&me?me:null;
const isRestricted=()=>document.body.classList.contains('ff-restricted');
const ready=()=>!!(client()&&user());
const errMsg=e=>{const m=String(e?.message||e||'Lỗi không xác định');return /relation .* does not exist|could not find the table|schema cache|permission denied/i.test(m)?t('Cơ sở dữ liệu giải đấu chưa được thiết lập. Quản trị viên cần chạy migration Free Fire trong Supabase.','Tournament database is not ready. Admin must apply the Free Fire migration.'):m};
function toast(message,bad=false){const e=$('#ffNotice')||$('#ffAdminNotice');if(!e){alert(message);return}e.textContent=message;e.className='ff-notice'+(bad?' bad':' good');e.hidden=false;}
const req=async promise=>{const r=await promise;if(r.error)throw r.error;return r.data};
const getApproved=mode=>st.players.filter(x=>x.mode===mode);
const nameFor=id=>st.players.find(x=>x.user_id===id)?.nickname||st.allRegs.find(x=>x.user_id===id)?.nickname||st.accounts.find(x=>x.user_id===id)?.alias||'—';
const teamKey=s=>String(s||'').trim().toLocaleLowerCase();
function survivalRanks(){const users=getApproved('survival');return users.map(u=>{
 const rows=st.br.filter(r=>r.user_id===u.user_id),kills=rows.reduce((s,r)=>s+r.kills,0),wins=rows.filter(r=>r.placement===1).length;
 const total=rows.reduce((s,r)=>s+placement(r.placement)+2*r.kills,0),last=rows.find(r=>r.match_no===5)?.placement||51;
 return {user_id:u.user_id,name:u.nickname,played:rows.length,kills,wins,total,last};
 }).sort((a,b)=>b.total-a.total||b.wins-a.wins||b.kills-a.kills||a.last-b.last||a.name.localeCompare(b.name,'vi'))}
function clashRanks(){if(st.draws.some(d=>d.mode==='clash'))return getApproved('clash').map(p=>{let wins=0,rounds=0,against=0,played=0;for(const d of st.draws.filter(d=>d.mode==='clash')){const m=st.clash.find(m=>m.match_no===d.round_no),q=d.pairs[0];if(!m)continue;const a=q.a.includes(p.user_id),b=q.b.includes(p.user_id);if(!a&&!b)continue;played++;const x=a?m.rounds_a:m.rounds_b,y=a?m.rounds_b:m.rounds_a;wins+=x>y?1:0;rounds+=x;against+=y}return {user_id:p.user_id,name:p.nickname,wins,rounds,against,played,points:wins*3}}).sort((a,b)=>b.points-a.points||(b.rounds-b.against)-(a.rounds-a.against)||b.rounds-a.rounds||a.name.localeCompare(b.name,'vi'));const names=[...new Set(getApproved('clash').map(x=>String(x.team_name||'').trim()).filter(Boolean))];
 return names.map(name=>{const games=st.clash.filter(m=>teamKey(m.team_a)===teamKey(name)||teamKey(m.team_b)===teamKey(name));let wins=0,forRounds=0,against=0;
 games.forEach(m=>{const side=teamKey(m.team_a)===teamKey(name);const a=side?m.rounds_a:m.rounds_b,b=side?m.rounds_b:m.rounds_a;wins+=a>b?1:0;forRounds+=a;against+=b});
 return {name,wins,rounds:forRounds,against,played:games.length,points:wins*3}}).sort((a,b)=>b.points-a.points||(b.rounds-b.against)-(a.rounds-a.against)||b.rounds-a.rounds||a.name.localeCompare(b.name,'vi'))}
function duelRank(){const approved=getApproved('duel');const final=st.duel.find(r=>r.stage==='Chung kết');const bronze=st.duel.find(r=>r.stage==='Tranh hạng ba');
 const win=r=>r?(r.score_a===5?r.player_a:r.player_b):null;
 const lose=r=>r?(r.score_a===5?r.player_b:r.player_a):null;
 const medals=[win(final),lose(final),win(bronze)];
 const all=approved.map(p=>{const rows=st.duel.filter(m=>m.player_a===p.user_id||m.player_b===p.user_id);let wins=0,diff=0;rows.forEach(m=>{const a=m.player_a===p.user_id?m.score_a:m.score_b,b=m.player_a===p.user_id?m.score_b:m.score_a;if(a===5)wins++;diff+=a-b});return {user_id:p.user_id,name:p.nickname,wins,diff,played:rows.length,medal:medals.indexOf(p.user_id)+1}});
 return all.sort((a,b)=>(a.medal?0:1)-(b.medal?0:1)||(a.medal||99)-(b.medal||99)||b.wins-a.wins||b.diff-a.diff||a.name.localeCompare(b.name,'vi'));
}
let ffEngraveSeq=0;
function ffEngraving(k,label){
 const id='ffmetal'+(++ffEngraveSeq), colors=k===1?['#fff2b2','#b67b22','#f6d477','#79501a']:k===2?['#e8eff9','#78899f','#c8d4e3','#414c5d']:['#ffd1a4','#a45b30','#e6a574','#67341f'];
 const size=label.length>15?13:label.length>10?15:19;
 return `<span class="ff-award-engraving" aria-label="${esc(label)}"><svg viewBox="0 0 240 40" preserveAspectRatio="xMidYMid meet" aria-hidden="true"><defs><linearGradient id="${id}g" x1="0" y1="0" x2="0" y2="1"><stop offset="0" stop-color="${colors[0]}"/><stop offset=".28" stop-color="${colors[2]}"/><stop offset=".48" stop-color="${colors[1]}"/><stop offset=".7" stop-color="${colors[2]}"/><stop offset="1" stop-color="${colors[3]}"/></linearGradient><path id="${id}p" d="M 8,24 Q 120,32 232,24"/></defs><g font-family="Arial, sans-serif" font-size="${size}" font-weight="800" letter-spacing=".65" text-anchor="middle"><text fill="${colors[3]}" stroke="#170f09" stroke-width="1.4" stroke-linejoin="round" transform="translate(0,1.6)"><textPath href="#${id}p" startOffset="50%">${esc(label.toLocaleUpperCase('vi-VN'))}</textPath></text><text fill="url(#${id}g)" stroke="${colors[3]}" stroke-width=".35" paint-order="stroke fill"><textPath href="#${id}p" startOffset="50%">${esc(label.toLocaleUpperCase('vi-VN'))}</textPath></text></g></svg></span>`;
}

function ffCup(k){return `<img class="ff-cup-svg ff-cup-photo" src="./assets/ff-cup-${k}.webp" alt="" aria-hidden="true" decoding="async">`}

const trophy=i=>i<3?`<span class="ff-mini-cup" aria-label="${t('Hạng','Rank')} ${i+1}">${ffCup(i+1)}<b>${i+1}</b></span>`:`#${i+1}`;
function ffPodium(rows,final,kind){
 const awards=[t('Giải Nhất','First prize'),t('Giải Nhì','Second prize'),t('Giải Ba','Third prize')];
 const modeLabel={solo:t('Sinh Tồn','Survival'),clash:t('Tử Chiến','Clash Squad'),duel:t('Độc Lang Chiến','Lone Wolf'),overall:''}[kind]||'';
 return `<div class="ff-live-podium">${[2,1,3].map(k=>{const r=kind==='duel'?rows.find(x=>x.medal===k):rows[k-1];const value=r?(kind==='solo'||kind==='overall'?r.total:kind==='clash'?r.points:null):null;const confirmed=!!r&&(kind==='duel'||final);return `<div class="ff-cup-card rank-${k} ${r?'':'unfilled'}"><div class="ff-cup-art"><div class="ff-statue-inscribed">${ffCup(k)}${ffEngraving(k,modeLabel||awards[k-1])}</div></div><div class="ff-cup-base"><small class="ff-winner-rank">${confirmed?awards[k-1]:t('Hạng','Rank')+' '+k}</small><strong class="ff-winner-name">${esc(r?.name||t('Chưa xác định','TBD'))}</strong>${value!==null?`<div class="ff-cup-points">${value} <small>${t('điểm','pts')}</small></div>`:''}<span class="ff-cup-state">${confirmed?t('Kết quả','Result'):r?t('Tạm thời','Provisional'):t('Chờ kết quả','Awaiting results')}</span></div></div>`}).join('')}</div>`;
}
const table=(heads,rows,empty=t('Chưa có kết quả được xác nhận.','No confirmed results yet.'))=>`<div class="ff-scroll"><table class="ff-table"><thead><tr>${heads.map(s=>`<th>${s}</th>`).join('')}</tr></thead><tbody>${rows.length?rows.join(''):`<tr><td colspan="${heads.length}" class="ff-empty">${empty}</td></tr>`}</tbody></table></div>`;
const badge=status=>`<span class="ff-status ${esc(status)}">${esc(({pending:t('Chờ duyệt','Pending'),approved:t('Đã duyệt','Approved'),rejected:t('Từ chối','Rejected')})[status]||status)}</span>`;
function rules(){return `<section class="ff-hero"><div class="ff-eyebrow">STUDYT / TOURNAMENT 2026</div><div class="ff-hero-main"><div><h2>FREE FIRE <span>CHAMPIONSHIP</span></h2><p>${t('Giải đấu tháng 11 · Ba chế độ · Thi đấu công bằng, kết quả minh bạch.','November tournament · Three modes · Fair play and transparent scoring.')}</p><div class="ff-hero-pills"><span>SOLO</span><span>CLASH SQUAD</span><span>LONE WOLF</span></div></div><div class="ff-hero-trophy" aria-hidden="true">${ffCup(1)}<small>2026</small></div></div></section>
 <div class="ff-days">${modes.map((m,i)=>`<article class="ff-day"><span class="ff-daynum">0${i+1} / ${m[3]}</span><h3>${lng()?m[2]:m[1]}</h3><p>${lng()?m[5]:m[4]}</p></article>`).join('')}</div>
 <article class="ff-rule-card"><div class="ff-kicker">01 — 19/11/2026 · SOLO BATTLE ROYALE</div><h3>${t('PHẦN 1 · SINH TỒN SOLO','PART 1 · SOLO SURVIVAL')}</h3><p>${t('Mỗi thí sinh tự thi đấu, không lập đội. Tổng cộng 5 trận; tính tổng điểm thứ hạng và hạ gục của cả 5 trận. Không được liên minh, cố ý nhường mạng hoặc hợp tác giữa các thí sinh.','Every contestant plays alone for 5 matches. Placement and elimination points accumulate across all 5 games. No teaming or match fixing.')}</p>
 ${table([t('Thứ hạng','Placement'),t('Điểm','Points'),t('Thứ hạng','Placement'),t('Điểm','Points')],[[1,20,'6',10],[2,17,'7',9],[3,15,'8',8],[4,13,'9',7],[5,12,'10',6]].map(r=>`<tr><td>Top ${r[0]}</td><td><strong>${r[1]}</strong></td><td>Top ${r[2]}</td><td><strong>${r[3]}</strong></td></tr>`))}
 <div class="ff-score-notes"><span>TOP 11–15 <b>5</b></span><span>TOP 16–20 <b>3</b></span><span>TOP 21–30 <b>2</b></span><span>TOP 31–40 <b>1</b></span><span>TOP 41–50 <b>0</b></span><span>${t('MỖI HẠ GỤC','PER ELIMINATION')} <b>+2</b></span></div><p class="ff-hint">${t('Ưu tiên khi bằng điểm: số Booyah → tổng số hạ gục → thứ hạng ở trận 5 → đối chiếu biên bản quản trị.','Tiebreaker: Booyah count → total eliminations → match 5 placement → administrator review.')}</p></article>
 <article class="ff-rule-card"><div class="ff-kicker">02 — 22/11/2026 · CLASH SQUAD</div><h3>${t('PHẦN 2 · TỬ CHIẾN','PART 2 · CLASH SQUAD')}</h3><p>${t('Thi đấu theo đội 4v4. Ban tổ chức tổ chức đúng 5 trận đối đầu. Mỗi trận tối đa 7 round; đội đạt 4 round thắng trước sẽ thắng trận (các tỷ số hợp lệ: 4–0, 4–1, 4–2, 4–3).','4v4 team battles across 5 fixtures. Each fixture is best of 7 rounds, first team to win 4 rounds wins (4–0 through 4–3).')}</p>
 <div class="ff-metrics"><div><strong>+3</strong><span>${t('Điểm mỗi trận thắng','Points per match win')}</span></div><div><strong>0</strong><span>${t('Điểm mỗi trận thua','Points per loss')}</span></div><div><strong>5</strong><span>${t('Trận toàn giải','Tournament fixtures')}</span></div></div><p class="ff-hint">${t('Xếp đội theo tổng điểm, hiệu số round, tổng round thắng. Quản trị viên bốc thăm đội hình 4 người trước từng trận; điểm được cộng cho từng thành viên đội thắng. Không sử dụng phần mềm can thiệp hay thông đồng.','Players rank by points, round differential and rounds won. Admin draws four-player teams for each match.')}</p></article>
 <article class="ff-rule-card"><div class="ff-kicker">03 — 25/11/2026 · LONE WOLF</div><h3>${t('PHẦN 3 · ĐỘC LANG CHIẾN','PART 3 · LONE WOLF')}</h3><p>${t('Đối kháng cá nhân 1v1 theo nhánh đấu do ban tổ chức công bố. Mỗi trận tối đa 9 round, đạt 5 round thắng trước là người chiến thắng. Có trận chung kết xác định hạng nhất, nhì và trận tranh hạng ba xác định hạng ba.','1v1 bracket matches. First to win 5 rounds (best of 9). The final decides first and second; the third-place playoff decides bronze.')}</p>
</article>
 <article class="ff-rule-card ff-conduct"><h3>${t('QUY TẮC THI ĐẤU VÀ XỬ LÝ VI PHẠM','FAIR PLAY & DISCIPLINE')}</h3><ul><li>${t('Sử dụng đúng UID, tài khoản và tên thi đấu đã được duyệt; không thay người trái phép.','Use the approved UID and player identity; no unauthorized substitution.')}</li><li>${t('Cấm hack, script, công cụ can thiệp, lỗi game có chủ đích, thông đồng, dàn xếp tỷ số hoặc xúc phạm người khác.','No cheats, scripts, exploits, collusion, match fixing or harassment.')}</li><li>${t('Vắng mặt quá 10 phút sau giờ ban tổ chức thông báo có thể bị xử thua; quyết định phải có biên bản.','More than 10 minutes late after announced check-in can result in forfeiture, documented by staff.')}</li><li>${t('Mất kết nối: thông báo ngay và cung cấp bằng chứng. Quản trị viên quyết định đấu lại hoặc giữ kết quả theo mức độ ảnh hưởng.','Report disconnections with evidence. Admins decide rematch or result retention case by case.')}</li><li>${t('Xử phạt dự kiến: nhắc nhở, hủy điểm trận hoặc loại khỏi giải; phải được ghi nhận cùng lý do, cho phép khiếu nại trước khi chốt kết quả.','Possible sanctions: warning, nullifying match points, or disqualification with documented reasons and an appeal opportunity.')}</li><li>${t('Giờ tập trung, bản đồ, danh sách phòng và thiết bị hợp lệ sẽ do ban tổ chức thông báo riêng trước ngày thi.','Check-in time, maps, custom room details and device rules will be announced separately.')}</li></ul><p class="ff-hint">${t('Đây là thể lệ giải nội bộ do ban tổ chức đề xuất, không phải quy định chính thức của Garena.','These are organizer-defined tournament rules, not official Garena tournament regulations.')}</p></article>
 <article class="ff-rule-card"><h3>${t('Xếp hạng tổng giải đấu','Overall standings')}</h3><p>${t('Bắt buộc thi đủ 3 ngày. Tổng điểm cá nhân = điểm Sinh tồn + điểm đội Tử chiến + 3 điểm mỗi trận thắng Độc Lang (thua 0). Bằng điểm ưu tiên Sinh tồn, Tử chiến, Độc Lang, sau đó tên game.','All three days are mandatory. Overall points = Survival + Clash team points + 3 per Lone Wolf win (0 per loss). Ties: Survival, Clash, Lone Wolf, then game name.')}</p></article><article class="ff-rule-card ff-rewards"><div class="ff-kicker">${t('PHẦN THƯỞNG TOÀN GIẢI','OVERALL TOURNAMENT PRIZES')}</div><h3>${t('PHẦN THƯỞNG','PRIZES')}</h3><p>${t('Phần thưởng dành cho ba thí sinh dẫn đầu bảng xếp hạng tổng sau cả 3 ngày thi đấu.','Prizes are awarded to the top three individual players in the overall standings after all three days.')}</p><div class="ff-reward-grid">${[[t('Giải Nhất','First prize'),t('01 thẻ tháng','01 monthly membership')],[t('Giải Nhì','Second prize'),t('01 thẻ tuần','01 weekly membership')],[t('Giải Ba','Third prize'),t('01 thẻ tuần VIP tiết kiệm','01 economy VIP weekly membership')]].map((r,i)=>`<div class="ff-reward rank-${i+1}"><span class="ff-reward-rank">0${i+1}</span><strong>${r[0]}</strong><span>${r[1]}</span></div>`).join('')}</div></article><div class="ff-consent"><label class="ff-agree"><input type="checkbox" id="ffRulesConsent"><span>${t('Tôi đã đọc và đồng ý với toàn bộ thể lệ, cách tính điểm và quy định xử lý vi phạm.','I have read and agree to the tournament rules, scoring and discipline policy.')}</span></label><button type="button" class="ff-main-btn" id="ffAgree">${t('ĐỒNG Ý THAM GIA','AGREE & REGISTER')} →</button></div>`}
function overallRanks(sur,cl,du){return sur.filter(r=>getApproved('clash').some(p=>p.user_id===r.user_id)&&getApproved('duel').some(p=>p.user_id===r.user_id)).map(r=>{const member=getApproved('clash').find(p=>p.user_id===r.user_id), c=cl.find(x=>x.user_id===r.user_id)||cl.find(x=>!x.user_id&&teamKey(x.name)===teamKey(member.team_name)), d=du.find(x=>x.user_id===r.user_id);const clash=c?.points||0,duel=(d?.wins||0)*3;return {...r,survival:r.total,clash,duel,total:r.total+clash+duel,duelPlayed:d?.played||0}}).sort((a,b)=>b.total-a.total||b.survival-a.survival||b.clash-a.clash||b.duel-a.duel||a.name.localeCompare(b.name,'vi'))}
function standings(){const sur=survivalRanks(),cl=clashRanks(),du=duelRank();
 const survivalFinal=sur.length>0&&sur.every(r=>r.played===5);
 const clashFinal=st.clash.length===5;
 const overall=overallRanks(sur,cl,du);
 const overallFinal=survivalFinal&&clashFinal&&overall.length===sur.length&&overall.every(r=>r.duelPlayed>0)&&du.filter(r=>r.medal).length===3;
 const totalBoard=table(['#',t('Tên game','In-game name'),t('Sinh tồn','Survival'),t('Tử chiến','Clash'),t('Độc Lang','Lone Wolf'),t('Tổng điểm','Total')],overall.map((r,i)=>`<tr><td>${overallFinal?trophy(i):'#'+(i+1)}</td><td>${esc(r.name)}</td><td>${r.survival}</td><td>${r.clash}</td><td>${r.duel}</td><td><strong>${r.total}</strong></td></tr>`));
 const one=table(['#',t('Thí sinh','Player'),t('Trận','Games'),'Booyah','Kills',t('Điểm','Points')],sur.map((r,i)=>`<tr><td class="ff-rank">${survivalFinal?trophy(i):'#'+(i+1)}</td><td><strong>${esc(r.name)}</strong></td><td>${r.played}/5</td><td>${r.wins}</td><td>${r.kills}</td><td><strong>${r.total}</strong></td></tr>`));
 const two=table(['#',t('Thí sinh / Đội','Player / Team'),t('Trận','Played'),t('Thắng','Wins'),t('Hiệu số','Diff'),t('Điểm','Points')],cl.map((r,i)=>`<tr><td class="ff-rank">${clashFinal?trophy(i):'#'+(i+1)}</td><td><strong>${esc(r.name)}</strong></td><td>${r.played}</td><td>${r.wins}</td><td>${r.rounds-r.against}</td><td><strong>${r.points}</strong></td></tr>`));
 const three=table(['#',t('Thí sinh','Player'),t('Trận','Played'),t('Thắng','Wins'),t('Hiệu số','Diff'),t('Danh hiệu','Award')],du.map((r,i)=>`<tr><td class="ff-rank">${r.medal?trophy(r.medal-1):`#${i+1}`}</td><td><strong>${esc(r.name)}</strong></td><td>${r.played}</td><td>${r.wins}</td><td>${r.diff}</td><td>${r.medal===1?t('Vô địch','Champion'):r.medal===2?t('Á quân','Runner-up'):r.medal===3?t('Hạng ba','Third'):'—'}</td></tr>`));
 return `<div class="ff-board-heading"><div><span class="ff-eyebrow">TOURNAMENT STANDINGS</span><h3>${t('Bảng xếp hạng giải đấu','Tournament leaderboards')}</h3></div><button class="ff-secondary" id="ffRefresh">↻ ${t('Cập nhật','Refresh')}</button></div><section class="ff-rule-card ff-standings-stage"><h3>🏆 ${t('Tổng giải đấu','Overall')}</h3><p>${t('Tổng = Sinh tồn + điểm đội Tử chiến + 3 điểm mỗi trận thắng Độc Lang. Bằng điểm: ưu tiên Sinh tồn, Tử chiến, Độc Lang, sau đó tên game.','Total = Survival + Clash team points + 3 per Lone Wolf win. Ties: Survival, Clash, Lone Wolf, then game name.')}</p>${ffPodium(overall,overallFinal,'overall')}${totalBoard}</section><section class="ff-rule-card ff-standings-stage"><h3>🏅 ${t('Sinh tồn','Survival')}</h3>${ffPodium(sur,survivalFinal,'solo')}${one}</section><section class="ff-rule-card ff-standings-stage"><h3>⚔️ ${t('Tử chiến','Clash Squad')}</h3>${ffPodium(cl,clashFinal,'clash')}${two}</section><section class="ff-rule-card ff-standings-stage"><h3>🏆 ${t('Độc Lang Chiến','Lone Wolf')}</h3>${ffPodium(du,false,'duel')}${three}</section>`}
function registration(){return `<section class="ff-rule-card"><div class="ff-kicker">PLAYER REGISTRATION</div><h3>${t('Đăng ký nội dung thi đấu','Register tournament modes')}</h3><p>${t('Hệ thống ghi nhận đăng ký bằng UID Free Fire của bạn. Mỗi thí sinh bắt buộc tham gia cả ba ngày; quản trị viên phải duyệt trước khi thi.','Your Free Fire UID identifies your registration. All three days are mandatory; administrator approval is required.')}</p>
 ${st.regs.length?`<div class="ff-reg-summary">${st.regs.map(r=>`<div><b>${esc(modes.find(m=>m[0]===r.mode)?.[lng()?2:1]||r.mode)}</b>${badge(r.status)}${r.admin_note?`<small>${esc(r.admin_note)}</small>`:''}</div>`).join('')}</div>`:''}
 <form id="ffRegForm"><div class="ff-form-row"><label>${t('UID Free Fire (chỉ số)','Free Fire UID (digits only)')}<input name="uid" inputmode="numeric" maxlength="20" pattern="[0-9]{5,20}" placeholder="1234567890" required value="${esc(st.regs[0]?.game_uid||'')}"></label><label>${t('Tên game','In-game name')}<input name="nickname" maxlength="60" minlength="2" required placeholder="Player name" value="${esc(st.regs[0]?.nickname||'')}"></label></div>
 <label class="ff-full">${t('Tên đội đăng ký (tham khảo, đội thi đấu do bốc thăm)','Registration team name (reference only; actual teams drawn)')}<input name="team" required maxlength="60" placeholder="Ví dụ: StudyT Warriors" value="${esc(st.regs.find(r=>r.mode==='clash')?.team_name||'')}"></label>
 <div class="ff-choices">${modes.map(m=>`<div class="ff-mode-check"><span aria-hidden="true">✓</span><span><strong>${lng()?m[2]:m[1]}</strong><small>${m[3]} · ${t('Bắt buộc','Required')}</small></span></div>`).join('')}</div>
 <label class="ff-agree"><input type="checkbox" name="consent" required><span>${t('Tôi xác nhận UID chính xác, cam kết tham gia đủ 3 ngày, đồng ý với thể lệ và việc lưu thông tin đăng ký.','I confirm my UID, commit to all three days, accept the rules and consent to registration processing.')}</span></label><div class="ff-actions"><button type="submit" class="ff-main-btn">${t('GỬI ĐĂNG KÝ','SUBMIT REGISTRATION')}</button><p class="ff-small">${t('Đăng ký cả ba nội dung cùng lúc. Liên hệ quản trị để điều chỉnh.','All three modes are registered together. Contact an admin to edit.')}</p></div></form></section>`}
function drawUser(){const app=$('#ffTournament');if(!app)return;if(!st.identity){app.hidden=true;$('#studyt-electronic-pane .studyt-electronic')?.classList.remove('ff-has-identity');return}app.hidden=false;
 $('#studyt-electronic-pane .studyt-electronic')?.classList.add('ff-has-identity');
 app.innerHTML=`<div class="ff-app-head"><div><span class="ff-eyebrow">STUDYT / ELECTRONIC</span><h2>${t('TRUNG TÂM GIẢI ĐẤU','TOURNAMENT CENTER')}</h2><p>${t('Xác nhận danh tính hoàn tất','Identity confirmed')}: <strong>${esc(st.identity.full_name)}</strong> · ${t('Mã ID','ID')}: ${esc(st.identity.student_code)}</p></div><div class="ff-identity-actions"><span class="ff-verified">✓ ${t('Đã xác nhận','Verified')}</span><button type="button" class="ff-secondary" id="ffEditIdentity">${t('Sửa thông tin','Edit identity')}</button></div></div>
 <div class="ff-tabs" role="tablist">${[['rules',t('Thể lệ','Rules')],['standings',t('Bảng xếp hạng','Leaderboard')],['register',t('Đăng ký','Register')]].map(([k,v])=>`<button type="button" data-ff-tab="${k}" class="${st.tab===k?'on':''}" role="tab" aria-selected="${st.tab===k}">${v}</button>`).join('')}</div><div id="ffNotice" class="ff-notice" hidden role="status" aria-live="polite"></div><div class="ff-panel">${st.tab==='rules'?rules():st.tab==='standings'?standings():registration()}</div>`;
 $$('[data-ff-tab]',app).forEach(b=>b.onclick=()=>{st.tab=b.dataset.ffTab;drawUser();});
 $('#ffAgree',app)?.addEventListener('click',()=>{if(!$('#ffRulesConsent',app).checked){toast(t('Vui lòng đánh dấu đã đọc và đồng ý với thể lệ.','Please accept the rules first.'),true);return}st.tab='register';drawUser();$('#ffRegForm',app)?.scrollIntoView({block:'nearest',behavior:'smooth'});});
 $('#ffRefresh',app)?.addEventListener('click',()=>loadUser(false));$('#ffRegForm',app)?.addEventListener('submit',submitRegistration);
 $('#ffEditIdentity',app)?.addEventListener('click',()=>{const card=$('#studyt-electronic-pane .studyt-electronic');card?.classList.remove('ff-has-identity');const f=$('#studyt-electronic-form');if(f){f.elements.studentId.value=st.identity.student_code||'';f.elements.fullName.value=st.identity.full_name||'';f.elements.birth.value=st.identity.birth_date||'';f.elements.agree.checked=false;f.scrollIntoView({behavior:'smooth',block:'start'});}});
}
async function nameGate(){
 if(!isRestricted())return true;
 const a=await req(client().from('ff_accounts').select('official_name,active').eq('user_id',user().id).single());
 if(!a.active)throw Error('Tài khoản đã bị khóa.');
 st.official=a.official_name;
 const form=$('#studyt-electronic-form');
 if(st.official){$('#ffNameGuide')?.remove();if(form){form.elements.fullName.value=st.official;form.elements.fullName.readOnly=true;}return true;}
 if($('#ffNameGuide'))return false;
 const overlay=document.createElement('div');overlay.id='ffNameGuide';overlay.innerHTML=`<section class="ff-name-spot" role="dialog" aria-modal="true" aria-labelledby="ffNameTitle"><div class="ff-eyebrow">STUDYT · BƯỚC 1 / 2</div><h2 id="ffNameTitle">Đổi tên đăng nhập chính thức</h2><p>Nhập họ và tên đầy đủ có dấu. Từ lần sau, bạn có thể dùng họ tên này để đăng nhập với mật khẩu đã cấp.</p><form id="ffNameForm"><label>Họ và tên chính thức<input name="official" required minlength="3" maxlength="120" autocomplete="name" placeholder="Nguyễn Văn An"></label><p id="ffNameError" role="alert"></p><button class="ff-main-btn" type="submit">Lưu tên và tiếp tục →</button><button class="ff-secondary" type="button" id="ffNameLogout">Đăng xuất</button></form></section>`;
 document.body.append(overlay);const f=$('#ffNameForm');f.elements.official.focus();
 overlay.addEventListener('keydown',e=>{if(e.key!=='Tab')return;const items=[...overlay.querySelectorAll('input,button:not(:disabled)')];if(e.shiftKey&&document.activeElement===items[0]){e.preventDefault();items.at(-1).focus()}else if(!e.shiftKey&&document.activeElement===items.at(-1)){e.preventDefault();items[0].focus()}});
 $('#ffNameLogout').onclick=()=>doLogout();
 f.onsubmit=async e=>{e.preventDefault();const b=f.querySelector('button[type=submit]');b.disabled=true;try{const n=await req(client().rpc('ff_set_official_name',{p_name:f.elements.official.value.trim().replace(/\s+/g,' ')}));st.official=n;user().name=n;const who=$('#whoami');if(who)who.textContent=n+' · Điện tử';overlay.remove();await loadUser(true);if(form){form.elements.studentId.focus();form.scrollIntoView({block:'center',behavior:'smooth'});form.classList.add('ff-identity-spot');} }catch(e){$('#ffNameError').textContent=e.code==='23505'?'Họ tên đã được sử dụng. Liên hệ quản trị viên nếu trùng tên.':errMsg(e);}finally{b.disabled=false}};
 return false;
}
async function loadUser(readIdentity=true){if(!ready()||ADMIN||!isRestricted())return;try{
 if(!await nameGate())return;
 if(readIdentity){st.identity=await req(client().from('ff_identities').select('*').eq('user_id',user().id).maybeSingle());}
 if(!st.identity){drawUser();return}
 const [r,p,b,c,d,draws]=await Promise.all([
 req(client().from('ff_registrations').select('*').eq('user_id',user().id).order('created_at')),
 req(client().from('ff_public_players').select('*')),
 req(client().from('ff_br_results').select('*')),
 req(client().from('ff_clash_matches').select('*')),
 req(client().from('ff_duel_matches').select('*')),req(client().from('ff_draws').select('*'))]);
 st.draws=draws||[];st.regs=r||[];st.players=p||[];st.br=b||[];st.clash=c||[];st.duel=d||[];st.loaded=true;drawUser();
 }catch(e){drawUser();toast(errMsg(e),true)}}
async function submitRegistration(e){e.preventDefault();const f=e.currentTarget;if(!ready()||!isRestricted()||!st.identity)return toast(t('Phiên đăng nhập không hợp lệ.','Invalid login session.'),true);
 const uid=f.elements.uid.value.trim(),nickname=f.elements.nickname.value.trim(),team=f.elements.team.value.trim();
 const selected=modes.map(m=>m[0]).filter(m=>!st.regs.some(r=>r.mode===m));
 if(!/^[0-9]{5,20}$/.test(uid))return toast(t('UID phải gồm 5–20 chữ số.','UID must contain 5–20 digits.'),true);
 if(nickname.length<2||nickname.length>60)return toast(t('Tên game phải gồm 2–60 ký tự.','Nickname must contain 2–60 characters.'),true);
 if(!selected.length)return toast(t('Bạn đã đăng ký cả ba nội dung.','You have registered all three modes.'),true);
 if(selected.includes('clash')&&(team.length<2||team.length>60))return toast(t('Hãy nhập tên đội Tử chiến (2–60 ký tự).','Enter a Clash Squad team name (2–60 chars).'),true);
 if(!f.elements.consent.checked)return toast(t('Bạn cần đồng ý với điều khoản.','Accept the rules first.'),true);
 const button=$('button[type=submit]',f);button.disabled=true;try{await req(client().rpc('ff_register_all',{p_uid:uid,p_nickname:nickname,p_team:team}))
 st.tab='register';await loadUser(false);toast(t('Đã gửi đăng ký thành công. Vui lòng chờ quản trị viên duyệt.','Registration submitted; awaiting administrator approval.'));
 }catch(e){await loadUser(false);toast(errMsg(e),true)}finally{button.disabled=false}}
async function confirmIdentity({id,name,birth}){if(!ready()||!isRestricted())throw Error(t('Chỉ tài khoản thi đấu được cấp mới có quyền truy cập Điện tử.','Only issued tournament accounts may access Digital ID.'));
 if(isRestricted()&&!await nameGate())throw Error("Cần đổi tên chính thức trước.");
 if(isRestricted())name=st.official;
 const value={user_id:user().id,student_code:id,full_name:name,birth_date:birth};
 if(!/^.{3,64}$/.test(id)||name.length<2||name.length>120||!/^[0-9]{4}-[0-9]{2}-[0-9]{2}$/.test(birth))throw Error(t('Thông tin xác nhận chưa hợp lệ.','Invalid identity fields.'));
 if(new Date(birth+'T00:00:00')>new Date())throw Error(t('Ngày sinh không được ở tương lai.','Birth date cannot be in the future.'));
 await req(client().from('ff_identities').upsert(value,{onConflict:'user_id'}));st.identity={...value,confirmed_at:new Date().toISOString()};st.tab='rules';
 $('#studyt-electronic-form')?.classList.remove('ff-identity-spot');await loadUser(false);return true;
}
function accountName(id){return st.identities.find(x=>x.user_id===id)?.full_name||st.accounts.find(x=>x.user_id===id)?.alias||nameFor(id)}
function adminRegistrationTable(){const statuses={pending:t('Chờ duyệt','Pending'),approved:t('Đã duyệt','Approved'),rejected:t('Từ chối','Rejected')};
 return `<div class="ff-admin-kpis"><div><strong>${st.allRegs.length}</strong><small>${t('Lượt đăng ký','Registrations')}</small></div><div><strong>${st.allRegs.filter(x=>x.status==='approved').length}</strong><small>${t('Đã duyệt','Approved')}</small></div><div><strong>${st.allRegs.filter(x=>x.status==='pending').length}</strong><small>${t('Chờ duyệt','Pending')}</small></div><div><strong>${st.accounts.length}</strong><small>${t('Tài khoản giải đấu','Tournament accounts')}</small></div></div>
 <div class="ff-toolbar"><input id="ffSearch" placeholder="${t('Tìm tên, UID, đội, tài khoản…','Search names, UID, team…')}" aria-label="${t('Tìm kiếm','Search')}"><select id="ffStatusFilter"><option value="">${t('Tất cả trạng thái','All statuses')}</option>${Object.entries(statuses).map(([k,v])=>`<option value="${k}">${v}</option>`).join('')}</select><button id="ffExport" class="ff-secondary">↓ CSV</button></div><div id="ffRegRows"></div>`}
function renderRegistrationRows(){const root=$('#ffRegRows');if(!root)return;const q=($('#ffSearch')?.value||'').toLowerCase().trim(),filter=$('#ffStatusFilter')?.value||'';
 const list=st.allRegs.filter(r=>(!filter||r.status===filter)&&(!q||[r.nickname,r.game_uid,r.team_name,accountName(r.user_id),st.identities.find(x=>x.user_id===r.user_id)?.student_code].some(x=>String(x||'').toLowerCase().includes(q))));
 root.innerHTML=table(['#',t('Thí sinh / ID','Participant / ID'),'UID',t('Nội dung / Đội','Mode / Team'),t('Trạng thái','Status'),t('Thao tác','Actions')],list.map(r=>{const id=st.identities.find(x=>x.user_id===r.user_id);return `<tr><td>${r.id}</td><td><strong>${esc(id?.full_name||r.nickname)}</strong><small>${esc(id?.student_code||'—')} · ${id?.birth_date||'—'}</small></td><td>${esc(r.game_uid)}<small>${esc(r.nickname)}</small></td><td>${esc(modes.find(m=>m[0]===r.mode)?.[lng()?2:1]||r.mode)}<small>${esc(r.team_name||'')}</small></td><td>${badge(r.status)}</td><td><div class="ff-cell-actions"><button data-ff-status="approved" data-reg-id="${r.id}" ${r.status==='approved'?'disabled':''}>✓ ${t('Duyệt','Approve')}</button><button data-ff-status="rejected" data-reg-id="${r.id}" ${r.status==='rejected'?'disabled':''}>✕ ${t('Từ chối','Reject')}</button></div></td></tr>`}),t('Không có đăng ký phù hợp.','No matching registrations.'));
 $$('button[data-ff-status]',root).forEach(b=>b.onclick=()=>updateStatus(Number(b.dataset.regId),b.dataset.ffStatus));
}
function adminAccounts(){return `<section class="ff-rule-card"><h3>${t('15 tài khoản cố định · quyền Điện tử','15 fixed accounts · Digital ID only')}</h3><p>${t('Tài khoản được cấp qua công cụ quản trị Supabase. Khi đăng nhập chúng chỉ được mở Điện tử; các mục StudyT khác sẽ bị làm mờ và hạn chế truy cập. Mật khẩu không được hiển thị tại đây.','Provisioned via secure Supabase admin script. Tournament-only accounts cannot access other StudyT modules. Passwords are not displayed here.')}</p>
 ${table(['#',t('Tài khoản','Account'),t('Danh tính','Identity'),t('Quyền','Access'),t('Thao tác','Action')],st.accounts.map((a,i)=>`<tr><td>${i+1}</td><td><b>${esc(a.alias)}</b></td><td>${esc(a.official_name||st.identities.find(x=>x.user_id===a.user_id)?.full_name||t('Chưa đổi tên','Name pending'))}</td><td>${a.active?badge('approved'):badge('rejected')}</td><td><button class="ff-secondary" data-account-id="${a.user_id}" data-next="${!a.active}">${a.active?t('Tạm khóa','Disable'):t('Mở lại','Enable')}</button></td></tr>`),t('Chưa cấp tài khoản. Chạy tập lệnh provisioning.','No accounts provisioned. Run provisioning script.'))}</section>`}
function selectPeople(mode,id){const people=getApproved(mode);return `<select id="${id}" required><option value="">${t('Chọn thí sinh','Select participant')}</option>${people.map(x=>`<option value="${esc(x.user_id)}">${esc(x.nickname)}</option>`).join('')}</select>`}
function adminResults(){const teamNames=[...new Set(getApproved('clash').map(x=>x.team_name).filter(Boolean))];return `<div class="ff-admin-grid"><section class="ff-rule-card"><div class="ff-kicker">01 / SURVIVAL · 5 MATCHES</div><h3>${t('Nhập điểm Sinh tồn Solo','Solo survival results')}</h3><form id="ffBrForm"><label>${t('Thí sinh','Player')}${selectPeople('survival','ffBrPlayer')}</label><div class="ff-form-row"><label>${t('Trận số','Match')}<select name="match">${[1,2,3,4,5].map(n=>`<option>${n}</option>`).join('')}</select></label><label>${t('Xếp hạng','Placement')}<input type="number" name="place" min="1" max="50" required></label></div><label>${t('Số hạ gục','Eliminations')}<input type="number" name="kills" min="0" max="49" required></label><button class="ff-main-btn">${t('Lưu kết quả','Save result')}</button></form></section>
 <section class="ff-rule-card"><div class="ff-kicker">02 / CLASH · 5 FIXTURES</div><h3>${t('Nhập tỷ số Tử chiến','Clash Squad fixture result')}</h3><form id="ffClashForm"><label>${t('Trận số','Match')}<select name="match">${[1,2,3,4,5].map(n=>`<option>${n}</option>`).join('')}</select></label><div class="ff-form-row"><label>${t('Đội A','Team A')}<select name="teamA" required><option value="">${t('Chọn đội','Select team')}</option>${teamNames.map(s=>`<option>${esc(s)}</option>`).join('')}</select></label><label>${t('Đội B','Team B')}<select name="teamB" required><option value="">${t('Chọn đội','Select team')}</option>${teamNames.map(s=>`<option>${esc(s)}</option>`).join('')}</select></label></div><div class="ff-form-row"><label>Round A <input name="scoreA" type="number" min="0" max="4" required></label><label>Round B <input name="scoreB" type="number" min="0" max="4" required></label></div><button class="ff-main-btn">${t('Lưu trận','Save fixture')}</button></form></section>
 <section class="ff-rule-card"><div class="ff-kicker">03 / LONE WOLF</div><h3>${t('Nhập trận Độc Lang 1v1','Save Lone Wolf duel')}</h3><form id="ffDuelForm"><label>${t('Vòng đấu','Stage')}<select name="stage">${['Vòng loại','Tứ kết','Bán kết','Chung kết','Tranh hạng ba'].map(s=>`<option>${s}</option>`).join('')}</select></label><div class="ff-form-row"><label>${t('Người A','Player A')}${selectPeople('duel','ffDuelA')}</label><label>${t('Người B','Player B')}${selectPeople('duel','ffDuelB')}</label></div><div class="ff-form-row"><label>Round A <input name="scoreA" type="number" min="0" max="5" required></label><label>Round B <input name="scoreB" type="number" min="0" max="5" required></label></div><button class="ff-main-btn">${t('Lưu trận 1v1','Save duel')}</button></form><p class="ff-hint">${t('Người thắng chung kết nhận cúp vô địch, người thua nhận bạc; người thắng trận tranh hạng ba nhận đồng.','The champion, runner-up and bronze are derived automatically from the final and third-place playoff.')}</p></section></div>
 <section class="ff-rule-card"><h3>${t('Kết quả đã ghi nhận','Recorded results')}</h3><div class="ff-admin-logs"><div><h4>Sinh tồn</h4>${table([t('Trận','Match'),t('Người chơi','Player'),'Top','Kills',''],st.br.sort((a,b)=>a.match_no-b.match_no).map(r=>`<tr><td>${r.match_no}</td><td>${esc(nameFor(r.user_id))}</td><td>${r.placement}</td><td>${r.kills}</td><td><button class="ff-icon-btn" data-del-table="ff_br_results" data-del-id="${r.id}" aria-label="Xóa">✕</button></td></tr>`))}</div><div><h4>Tử chiến</h4>${table([t('Trận','Match'),t('Đội A','Team A'),t('Đội B','Team B'),t('Tỷ số','Score'),''],st.clash.map(r=>`<tr><td>${r.match_no}</td><td>${esc(r.team_a)}</td><td>${esc(r.team_b)}</td><td>${r.rounds_a}–${r.rounds_b}</td><td><button class="ff-icon-btn" data-del-table="ff_clash_matches" data-del-id="${r.match_no}">✕</button></td></tr>`))}</div><div><h4>Độc Lang</h4>${table([t('Vòng','Stage'),t('Thí sinh A','Player A'),t('Thí sinh B','Player B'),t('Tỷ số','Score'),''],st.duel.map(r=>`<tr><td>${esc(r.stage)}</td><td>${esc(nameFor(r.player_a))}</td><td>${esc(nameFor(r.player_b))}</td><td>${r.score_a}–${r.score_b}</td><td><button class="ff-icon-btn" data-del-table="ff_duel_matches" data-del-id="${r.id}">✕</button></td></tr>`))}</div></div></section>`}
function drawPanel(){const eligible=mode=>st.accounts.filter(a=>a.active&&a.official_name&&/^ffplayer(0[1-9]|1[0-5])$/.test(a.alias)&&st.allRegs.some(r=>r.user_id===a.user_id&&r.mode===mode&&r.status==='approved'));const nm=id=>esc(st.accounts.find(a=>a.user_id===id)?.official_name||nameFor(id));return `<section class="ff-rule-card"><h3>Bốc thăm Tử chiến · 4v4</h3><p>${eligible('clash').length} thí sinh đủ điều kiện (đã đổi tên, đang hoạt động, đã duyệt). Ưu tiên người ít lượt thi đấu. Chốt tỷ số sẽ khóa đội hình.</p>${[1,2,3,4,5].map(n=>{const d=st.draws.find(d=>d.mode==='clash'&&d.round_no===n),m=st.clash.find(m=>m.match_no===n);return `<div class="ff-rule-card"><h4>Trận ${n}</h4>${!m?`<button class="ff-secondary" data-draw="clash" data-round="${n}">${d?'Random lại':'Random đội'}</button>`:''}${d?`<div class="ff-form-row"><div><b>Đội A</b>${d.pairs[0].a.map(id=>`<p>${nm(id)}</p>`).join('')}</div><div><b>Đội B</b>${d.pairs[0].b.map(id=>`<p>${nm(id)}</p>`).join('')}</div></div>${m?`<b>Đã chốt: ${m.rounds_a}–${m.rounds_b}</b>`:scoreForm('clash',n,0,4)}`:m?'Kết quả cũ đã lưu':''}</div>`}).join('')}</section><section class="ff-rule-card"><h3>Bốc thăm Độc Lang Chiến · 1v1</h3><p>${eligible('duel').length} thí sinh đủ điều kiện. Mỗi vòng chỉ bốc một lần; chỉ người thắng đi tiếp, ngoại trừ trận tranh hạng ba.</p>${[1,2,3,4].map(n=>{const d=st.draws.find(d=>d.mode==='duel'&&d.round_no===n);return `<div class="ff-rule-card"><h4>${['Vòng loại','Tứ kết','Bán kết','Chung kết & tranh hạng ba'][n-1]}</h4>${d?`<b>🔒 Đã khóa bốc thăm</b>${d.pairs.map((p,i)=>{const m=st.duel.find(m=>m.stage===p.stage&&m.player_a===p.a&&m.player_b===p.b);return `<div class="ff-rule-card"><b>${nm(p.a)} ${p.b?' vs '+nm(p.b):' · Miễn đấu'}</b><p>${esc(p.stage)}</p>${p.b?(m?`<p>Đã chốt ${m.score_a}–${m.score_b} · Thắng: ${nm(m.score_a===5?p.a:p.b)}</p>`:scoreForm('duel',n,i,5)):''}</div>`}).join('')}`:`<button class="ff-main-btn" data-draw="duel" data-round="${n}">Bốc thăm và khóa</button>`}</div>`}).join('')}</section>`}
function scoreForm(mode,n,i,max){return `<form data-draw-score="${mode}" data-round="${n}" data-pair="${i}"><div class="ff-form-row"><label>Điểm A<input name="a" type="number" min="0" max="${max}" required></label><label>Điểm B<input name="b" type="number" min="0" max="${max}" required></label></div><button class="ff-main-btn">Chốt kết quả</button></form>`}
function bindDraw(){const pane=$('#studyt-ff-admin-pane');$$('[data-draw]',pane).forEach(b=>b.onclick=async()=>{if(!confirm(b.dataset.draw==='duel'?'Bốc thăm sẽ khóa vĩnh viễn vòng này. Tiếp tục?':'Random đội cho trận này?'))return;b.disabled=true;try{await req(client().rpc('ff_draw',{p_mode:b.dataset.draw,p_round:Number(b.dataset.round)}));await loadAdmin()}catch(e){toast(errMsg(e),true);b.disabled=false}});$$('[data-draw-score]',pane).forEach(f=>f.onsubmit=async e=>{e.preventDefault();if(!confirm('Chốt kết quả? Không thể sửa trực tiếp sau khi chốt.'))return;const b=f.querySelector('button');b.disabled=true;try{await req(client().rpc('ff_draw_score',{p_mode:f.dataset.drawScore,p_round:Number(f.dataset.round),p_pair:Number(f.dataset.pair),p_a:Number(f.elements.a.value),p_b:Number(f.elements.b.value)}));await loadAdmin()}catch(e){toast(errMsg(e),true);b.disabled=false}})}
function drawAdmin(){const pane=$('#studyt-ff-admin-pane');if(!pane)return;
 pane.innerHTML=`<section class="ff-admin-wrap"><div class="ff-app-head"><div><span class="ff-eyebrow">STUDYT ADMIN / FREE FIRE</span><h2>${t('QUẢN TRỊ GIẢI ĐẤU','TOURNAMENT ADMIN')}</h2><p>${t('Đăng ký · Kết quả · Tài khoản · Cúp vô địch','Registrations · Results · Accounts · Trophies')}</p></div><button class="ff-secondary" id="ffAdminReload">↻ ${t('Tải lại','Reload')}</button></div><div class="ff-tabs">${[['registrations',t('Thí sinh','Participants')],['results',t('Nhập điểm','Enter scores')],['draw','Bốc thăm thi đấu'],['leaderboard',t('Xếp hạng & cúp','Leaderboard & trophies')],['accounts',t('15 tài khoản','15 accounts')]].map(([k,v])=>`<button data-ff-admin-tab="${k}" class="${st.adminTab===k?'on':''}">${v}</button>`).join('')}</div><div id="ffAdminNotice" class="ff-notice" role="status" hidden></div>
 ${st.adminTab==='registrations'?adminRegistrationTable():st.adminTab==='results'?adminResults():st.adminTab==='draw'?drawPanel():st.adminTab==='leaderboard'?standings():adminAccounts()}</section>`;
 $$('[data-ff-admin-tab]',pane).forEach(b=>b.onclick=()=>{st.adminTab=b.dataset.ffAdminTab;drawAdmin()});$('#ffAdminReload')?.addEventListener('click',loadAdmin);
 if(st.adminTab==='registrations'){$('#ffSearch').oninput=renderRegistrationRows;$('#ffStatusFilter').onchange=renderRegistrationRows;$('#ffExport').onclick=exportCsv;renderRegistrationRows()}
 if(st.adminTab==='draw')bindDraw();
 if(st.adminTab==='results'){
 $('#ffBrForm').onsubmit=submitBr;$('#ffClashForm').closest('section').hidden=true;$('#ffDuelForm').closest('section').hidden=true;
 $$('[data-del-table]',pane).filter(b=>b.dataset.delTable!=='ff_br_results').forEach(b=>b.hidden=true);
 $$('[data-del-table]',pane).forEach(b=>b.onclick=()=>delResult(b.dataset.delTable,b.dataset.delId))}
 if(st.adminTab==='accounts'){$$('[data-account-id]',pane).forEach(b=>b.onclick=()=>toggleAccount(b.dataset.accountId,b.dataset.next==='true'))}
 $('#ffRefresh',pane)?.addEventListener('click',loadAdmin);
}
async function loadAdmin(){if(!ready()||!ADMIN||user().role!=='admin')return;try{
 const [a,i,r,p,b,c,d,draws]=await Promise.all([
 req(client().from('ff_accounts').select('*').order('alias')),
 req(client().from('ff_identities').select('*')),
 req(client().from('ff_registrations').select('*').order('created_at',{ascending:false})),
 req(client().from('ff_public_players').select('*')),
 req(client().from('ff_br_results').select('*')),
 req(client().from('ff_clash_matches').select('*').order('match_no')),
 req(client().from('ff_duel_matches').select('*').order('id')),req(client().from('ff_draws').select('*'))]);
 Object.assign(st,{draws:draws||[],accounts:a||[],identities:i||[],allRegs:r||[],players:p||[],br:b||[],clash:c||[],duel:d||[]});drawAdmin();
 }catch(e){drawAdmin();toast(errMsg(e),true)}}
async function updateStatus(id,status){if(!ADMIN||user()?.role!=='admin')return;const registration=st.allRegs.find(x=>x.id===id);if(!registration)return;
 let note=null;if(status==='rejected'){note=prompt(t('Lý do từ chối (tối đa 300 ký tự):','Reason for rejection (max 300 chars):'));if(note===null)return;note=note.slice(0,300)}
 if(!confirm(t(`Xác nhận ${status==='approved'?'duyệt':'từ chối'} đăng ký của ${registration.nickname}?`,`Confirm ${status} for ${registration.nickname}?`)))return;
 try{await req(client().from('ff_registrations').update({status,admin_note:note}).eq('id',id));await loadAdmin();toast(t('Đã cập nhật trạng thái đăng ký.','Registration status updated.'))}catch(e){toast(errMsg(e),true)}}
async function submitBr(e){e.preventDefault();const f=e.currentTarget,participant=$('#ffBrPlayer').value,m=safeNum(f.elements.match.value,1,5),place=safeNum(f.elements.place.value,1,50),kills=safeNum(f.elements.kills.value,0,49);
 if(!participant||m===null||place===null||kills===null)return toast(t('Vui lòng nhập đủ dữ liệu hợp lệ.','Complete all valid fields.'),true);
 try{await req(client().from('ff_br_results').upsert({user_id:participant,match_no:m,placement:place,kills,updated_at:new Date().toISOString()},{onConflict:'user_id,match_no'}));await loadAdmin();toast(t('Đã lưu điểm Sinh tồn.','Survival score saved.'))}catch(e){toast(errMsg(e),true)}}
async function submitClash(e){e.preventDefault();const f=e.currentTarget,a=f.elements.teamA.value,b=f.elements.teamB.value,m=safeNum(f.elements.match.value,1,5),x=safeNum(f.elements.scoreA.value,0,4),y=safeNum(f.elements.scoreB.value,0,4);
 if(!a||!b||teamKey(a)===teamKey(b)||m===null||x===null||y===null||!(x===4&&y<4||y===4&&x<4))return toast(t('Chọn hai đội khác nhau và tỷ số hợp lệ (4–0 đến 4–3).','Select different teams and a valid 4–0 to 4–3 score.'),true);
 try{await req(client().from('ff_clash_matches').upsert({match_no:m,team_a:a,team_b:b,rounds_a:x,rounds_b:y,updated_at:new Date().toISOString()},{onConflict:'match_no'}));await loadAdmin();toast(t('Đã lưu trận Tử chiến.','Clash match saved.'))}catch(e){toast(errMsg(e),true)}}
async function submitDuel(e){e.preventDefault();const f=e.currentTarget,a=$('#ffDuelA').value,b=$('#ffDuelB').value,x=safeNum(f.elements.scoreA.value,0,5),y=safeNum(f.elements.scoreB.value,0,5),stage=f.elements.stage.value;
 if(!a||!b||a===b||x===null||y===null||!(x===5&&y<5||y===5&&x<5))return toast(t('Chọn 2 người khác nhau và tỷ số hợp lệ (5–0 đến 5–4).','Select different players and a valid 5–0 to 5–4 score.'),true);
 if((stage==='Chung kết'||stage==='Tranh hạng ba')&&st.duel.some(r=>r.stage===stage))return toast(t('Vòng này đã có kết quả. Hãy xóa kết quả cũ nếu cần sửa.','This stage already has a result; delete it before replacing.'),true);
 try{await req(client().from('ff_duel_matches').insert({stage,player_a:a,player_b:b,score_a:x,score_b:y}));await loadAdmin();toast(t('Đã lưu trận Độc Lang và cập nhật cúp nếu có.','Duel saved; podium updated if applicable.'))}catch(e){toast(errMsg(e),true)}}
async function delResult(table,id){if(!['ff_br_results','ff_clash_matches','ff_duel_matches'].includes(table)||!confirm(t('Xóa kết quả trận này?','Delete this match result?')))return;
 try{const k=table==='ff_clash_matches'?'match_no':'id';await req(client().from(table).delete().eq(k,id));await loadAdmin();toast(t('Đã xóa kết quả.','Result deleted.'))}catch(e){toast(errMsg(e),true)}}
async function toggleAccount(id,next){if(!confirm(next?t('Mở lại tài khoản này?','Enable this account?'):t('Tạm khóa tài khoản giải đấu này?','Disable this tournament account?')))return;
 try{await req(client().from('ff_accounts').update({active:next}).eq('user_id',id));await loadAdmin();toast(t('Đã cập nhật quyền truy cập.','Access updated.'))}catch(e){toast(errMsg(e),true)}}
function exportCsv(){const rows=[['Mã đăng ký','Họ tên','Mã ID','Ngày sinh','UID Free Fire','Tên game','Nội dung','Đội','Trạng thái','Thời gian đăng ký','Ghi chú quản trị'],...st.allRegs.map(r=>{const x=st.identities.find(i=>i.user_id===r.user_id);return[r.id,x?.full_name||'',x?.student_code||'',x?.birth_date||'',r.game_uid,r.nickname,r.mode,r.team_name||'',r.status,r.created_at,r.admin_note||'']})];
 const fmtCell=c=>{let s=String(c??'');if(/^[\s]*[=+@-]/.test(s))s="'"+s;return'"'+s.replace(/"/g,'""')+'"'};const csv='\ufeff'+rows.map(r=>r.map(fmtCell).join(',')).join('\r\n');const u=URL.createObjectURL(new Blob([csv],{type:'text/csv;charset=utf-8'}));const a=document.createElement('a');a.href=u;a.download='StudyT-FreeFire-DanhSach.csv';a.click();setTimeout(()=>URL.revokeObjectURL(u),1000)}
function mount(){if(ADMIN){const bar=$('#homeTabs'),landing=$('#landingView');if(!bar||!landing)return false;
 if(!$('#ffAdminNav')){const b=document.createElement('button');b.id='ffAdminNav';b.dataset.p='ffadmin';b.type='button';b.innerHTML='<span class="ic">🏆</span><span>'+t('Giải đấu Free Fire','Free Fire Tournament')+'</span>';const foot=$('.stux-sidefoot',bar);foot?bar.insertBefore(b,foot):bar.append(b);b.addEventListener('click',()=>setTimeout(loadAdmin,10))}
 if(!$('#studyt-ff-admin-pane')){const p=document.createElement('div');p.id='studyt-ff-admin-pane';p.className='home-pane';p.dataset.pane='ffadmin';landing.append(p)}
 }else{const pane=$('#studyt-electronic-pane');if(!pane)return false;
 if(!$('#ffTournament')){const app=document.createElement('div');app.id='ffTournament';app.className='ff-tournament';app.hidden=true;pane.append(app);}
 const b=$('#homeTabs button[data-p="dientu"]');if(b&&!b.dataset.ffBound){b.dataset.ffBound='1';b.addEventListener('click',()=>{if(ready())loadUser(true)})}
 }return true}
function updateNav(){if(ADMIN)return;
 const nav=$('#homeTabs button[data-p="dientu"]');const pane=$('#studyt-electronic-pane');const allowed=isRestricted()&&ready();
 if(nav){nav.classList.toggle('ff-access-denied',!allowed);nav.setAttribute('aria-disabled',String(!allowed));}
 if(pane){pane.inert=!allowed;if(!allowed&&pane.classList.contains('on')){$('#homeTabs button[data-p="home"]')?.click();pane.classList.remove('on');}}
 if(!allowed)return;const btn=$('#homeTabs button[data-p="dientu"]');if(btn){const p=$('#landingView .home-pane.on');if(!p||p.dataset.pane!=='dientu')btn.click()}}
function onLogin(){setTimeout(()=>{mount();if(ADMIN)return;updateNav();const pane=$('#studyt-electronic-pane');if(pane&&ready())loadUser(true)},70)}
function onLogout(){$('#ffNameGuide')?.remove();const f=$('#studyt-electronic-form');if(f){f.elements.fullName.readOnly=false;f.classList.remove('ff-identity-spot');}Object.assign(st,{draws:[],official:null,identity:null,regs:[],players:[],br:[],clash:[],duel:[],loaded:false});const x=$('#ffTournament');if(x){x.hidden=true;x.innerHTML=''}}
window.StudyTFreeFire={confirm:confirmIdentity,onLogin,onLogout,loadUser,loadAdmin,openElectronic(){if(!isRestricted())return;mount();$('#homeTabs button[data-p="dientu"]')?.click();}};
if(!ADMIN)document.addEventListener('click',e=>{if(e.target.closest?.('#homeTabs button[data-p="dientu"]')&&(!ready()||!isRestricted())){e.preventDefault();e.stopImmediatePropagation();alert(t('Khu vực Điện tử chỉ dành cho 15 tài khoản thi đấu được ban tổ chức cấp.','Digital ID is restricted to the 15 issued tournament accounts.'));}},true);
if(document.readyState==='loading')document.addEventListener('DOMContentLoaded',()=>{mount();updateNav();},{once:true});else {mount();updateNav();}
new MutationObserver(()=>{if(!$('#ffTournament')&&!ADMIN||ADMIN&&!$('#studyt-ff-admin-pane')){mount();updateNav()}}).observe(document.body,{childList:true,subtree:true});
new MutationObserver(()=>{if(ready()){if(ADMIN&&$('#studyt-ff-admin-pane')?.classList.contains('on'))loadAdmin();else if(!ADMIN&&$('#studyt-electronic-pane')?.classList.contains('on'))loadUser(true)}updateNav()}).observe(document.body,{attributes:true,subtree:false,attributeFilter:['class']});
})();
